SELECT o.*, a.end_date_time FROM raffle_activity_order o
LEFT JOIN raffle_activity a ON o.activity_id = a.activity_id
WHERE 1=1

    AND user_id=#{userId}


    AND activity_id=#{activityId}


    AND state=#{orderState}

ORDER BY create_time DESC LIMIT #{offset},#{limit}

